import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Manual install","description":"Install PostgreSQL on Windows, macOS and Linux, download the matching Release archive by prefix, configure the three YAML files, start on boot.","frontmatter":{"title":"Manual install","description":"Install PostgreSQL on Windows, macOS and Linux, download the matching Release archive by prefix, configure the three YAML files, start on boot."},"headers":[],"relativePath":"en/guide/install/manual.md","filePath":"en/guide/install/manual.md","lastUpdated":1790057721000}`),a={name:`en/guide/install/manual.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="manual-install" tabindex="-1">Manual install <a class="header-anchor" href="#manual-install" aria-label="Permalink to “Manual install”">​</a></h1><p>This section goes from &quot;PostgreSQL is installed (Redis optional)&quot; to &quot;the process is listening and the browser can open the admin console&quot;. Official Releases <strong>do not</strong> require copying <code>frontend/dist</code>.</p><div class="warning custom-block"><p class="custom-block-title">Binary source</p><p>Open <a href="https://github.com/Kirizu-Official/KiriVers/releases" target="_blank" rel="noreferrer">https://github.com/Kirizu-Official/KiriVers/releases</a> and download the archive matching your <strong>prefix</strong> as listed on <a href="/en/guide/install/#releases-files">Choose an install path</a> — for example <code>KiriVers-Windows-x86_64-&lt;hash&gt;.zip</code>, <code>KiriVers-Linux-arm64-&lt;hash&gt;.zip</code>. Extracting gives <code>kirivers-&lt;os&gt;-&lt;arch&gt;</code> (<code>.exe</code> on Windows). Follow the current Release and do not use guessed direct links: the hash at the end of the filename changes every release.</p></div><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to “Windows”">​</a></h2><ol><li>Install the <a href="https://www.postgresql.org/download/windows/" target="_blank" rel="noreferrer">PostgreSQL Windows installer</a>. Record the superuser password and port you chose (default <code>5432</code>). Create a database and a role, for example database <code>kirivers</code> and user <code>kirivers</code>.</li><li>Redis: on a single machine you can skip it and use <code>cache.driver=memory</code>. If you do need Redis, install a Windows Redis build or run only Redis in Docker.</li><li>Download the matching prefix from Releases (<code>KiriVers-Windows-x86_64-</code>, <code>-x86-</code> or <code>-arm64-</code>) and put the extracted <code>.exe</code> in a stable directory, for example <code>C:\\KiriVers\\</code>.</li><li>Copy the repository&#39;s <code>configs/config-example.yaml</code>, <code>admin-example.yaml</code> and <code>client-example.yaml</code> into that same directory, renaming them <code>config.yaml</code>, <code>admin.yaml</code> and <code>client.yaml</code>. Edit the keys that <strong>must</strong> change before it will start — Notepad or VS Code is fine: <ul><li><code>postgres.dsn</code>: host, user, password, database, port</li><li><code>url_signing_secret</code> in production (otherwise signed download URLs die after a restart) Remaining keys: <a href="/en/guide/config/">Configuration</a>.</li></ul></li><li>Open a terminal in that directory:</li></ol><div class="language-bat line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">kirivers.exe</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>No arguments equals <code>kirivers server</code>. Expect the process to stay running and the logs to show the client <code>:8080</code> and admin <code>:8081</code> listeners.</p><ol start="6"><li>Open <code>http://127.0.0.1:8081</code> in a browser. You should see the login page (“Sign in to KiriVers”). If you only see JSON: check whether <code>static_dir</code> in <code>admin.yaml</code> is the empty string (that <strong>disables the UI</strong>), and whether you are running a self-built binary produced without building the admin console. Official Releases already embed the console.</li></ol><details class="details custom-block"><summary>:8081 shows JSON only</summary><p><code>static_dir: &quot;&quot;</code> disables the UI even when the binary embeds <code>index.html</code>. A self-built binary that never ran <code>yarn build</code> in <code>frontend/</code> may have no <code>index.html</code> in the embedded FS. Official Releases do <strong>not</strong> require copying <code>frontend/dist</code>.</p></details><ol start="7"><li>Start on boot: Task Scheduler → Create Basic Task → trigger &quot;When the computer starts&quot; → action &quot;Start a program&quot; pointing at <code>kirivers.exe</code>, started in the directory holding the configuration files.</li></ol><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to “macOS”">​</a></h2><p>PostgreSQL: Homebrew <code>brew install postgresql@17</code> or <a href="https://postgresapp.com/" target="_blank" rel="noreferrer">Postgres.app</a>. Redis optional with <code>brew install redis</code>. Download the <code>darwin</code> archive from Releases (prefix <code>KiriVers-macOS-</code>), copy the three YAML files, run <code>./kirivers</code> in a terminal. Open <code>http://127.0.0.1:8081</code>.</p><h2 id="linux-when-you-did-not-use-the-one-click-script" tabindex="-1">Linux (when you did not use the one-click script) <a class="header-anchor" href="#linux-when-you-did-not-use-the-one-click-script" aria-label="Permalink to “Linux (when you did not use the one-click script)”">​</a></h2><div class="vp-code-group"><div class="tabs"><input type="radio" name="group-85" id="tab-86" checked><label data-title="apt" for="tab-86">apt</label><input type="radio" name="group-85" id="tab-87"><label data-title="dnf" for="tab-87">dnf</label></div><div class="blocks"><div class="language-bash active line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-contrib</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql-setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --initdb</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></div></div><p>Download the Linux executable, copy the three YAML files, run <code>./kirivers</code>.</p><h3 id="systemd-example" tabindex="-1">systemd example <a class="header-anchor" href="#systemd-example" aria-label="Permalink to “systemd example”">​</a></h3><p>Replace <code>User</code>, <code>WorkingDirectory</code> and <code>ExecStart</code> with your real paths:</p><div class="language-ini line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=KiriVers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network.target postgresql.service</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=kirivers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WorkingDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/kirivers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/kirivers/kirivers -config /opt/kirivers</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><ul><li><code>WorkingDirectory</code>: the directory holding the three YAML files (or point <code>-config</code> at it).</li><li><code>ExecStart</code>: the binary path. No extra arguments starts both planes.</li><li><code>After=postgresql.service</code>: best-effort wait for the database; PostgreSQL must be reachable at startup or the process fatals.</li></ul><p>Enable with <code>sudo systemctl enable --now kirivers</code>.</p><p>Next: <a href="/en/guide/config/bootstrap-admin">bootstrap the first admin</a>.</p>`,21)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};